    ],
    timestamp: "04:40 PM",
    date: "SUNDAY, 06 MARCH"
  },
  {
    id: "4",
    type: "file_added",
    user: { name: "Shannon Baker", initials: "SB" },
    action: "added",
    target: "document.csv",
    timestamp: "03:18 PM",
    date: "SUNDAY, 06 MARCH"
  },
  {
    id: "5",
    type: "mention",
